"""Hand-edited wording for scan alarms; no manuscript reading is changed."""
from pathlib import Path
import csv,json
OUT=Path(__file__).resolve().parents[1]
with (OUT/'readings.tsv').open() as f: rows=list(csv.DictReader(f,delimiter='\t'))
edits={
30:('Finite commutative H² hypothesis; positive-degree cohomology torsion','Check the topology and the field extensions quantified.','Ordinary p-cohomological dimension over an imperfect field does not control flat μ_p-cohomology.'),
31:('A changed group variable near line 126','Track the kernel and quotient through the Frobenius and smooth reductions.','The induction must apply the vanishing hypothesis to the required twisted kernel.'),
32:('N_G(h)K=G','Check the meanings of K and the Cartan algebra h.','For G=SL₂ over an algebraically closed field of characteristic p>2, K=ker(F), and h=Lie(T), the reduced part of N_G(h)K is N_G(T), smaller than G. The written justification fails under this reading.'),
33:('H^i(k,α_p)=0 for all i','Candidate: i≥2, or an additional perfect-field hypothesis.','H¹_fppf(k,α_p)=k/k^p, nonzero for k=F_p(t); all higher groups in degrees at least two vanish.'),
34:('I versus Z in a quotient or band','Determine whether the normalizer quotient or the centre is written.','The alternatives give different obstructions involving bands and gerbes; formal analogy cannot decide the ink.'),
35:('[K,K]=K, “en particulier sans centre”; later [K,K]=1','Check whether simplicity is assumed and whether the later 1 should be K.','Perfectness does not imply trivial centre: SL₂(F₅) is perfect with centre {±I}. The exact finite-group enumeration is saved.'),
36:('Z: centre or radical, said not to be defined over k','Candidate: the geometrically reduced connected radical, not the scheme-theoretic centre.','The displayed ideal x²−ay²−u² has coefficients in k and defines a k-subgroup. Its geometrically reduced ideal uses √a and need not descend.'),
37:('X_j versus X′_j in the pro-Hom formula','Keep source and target indices consistent with lim_j colim_i Hom(X_i,Y_j).','SGA4 VIII 7.9 uses this variance. Removing the target prime changes the object being compared.'),
38:('Equivalence or antiequivalence for points and fibre functors','The point categories are equivalent; the fibre-functor category is opposite to the topos-point category.','SGA4 VIII 7.8 defines the latter convention explicitly. The two category names cannot be interchanged in a variance assertion.'),
39:('F or G flat; y above y','Candidate: F flat, and y above s, subject to the ink.','The intended conclusion is flatness of G; assuming it would make that conclusion tautological. The fibrewise map needs a point over s.'),
40:('“et alors seulement” in the ampleness criterion','Check whether the converse is cancelled or restricted by positivity.','On an elliptic curve, O_E(−0) is not ample but induces an isomorphism to the dual. Finite faithful flatness alone cannot characterize ampleness.'),
41:('The nonzero qualification is cancelled in an intersection assertion','Candidate: require α≠0.','For α=0, the pullback line bundle is geometrically trivial and its intersection degree is zero.'),
42:('σ_i is of degree 2i','Candidate: degree i.','The identity ν(n+[t])=(n+t)^(2g) gives σ₁=2gt. General coefficient homogeneity also gives degree i.'),
43:('End(A) versus End⁰(A)','Check whether tensoring with Q is already implicit in End.','For the polarization diag(1,2) on E², Rosati sends E₁₂ to (1/2)E₂₁. Integral endomorphisms need not be preserved.'),
44:('The target or argument of φ_Dξ is uncertain','Determine whether the label denotes D₂(L) or the line-bundle homomorphism.','D₂(L) is a line bundle on A×A; φ_L is a morphism A→A∨. Confusing them changes the type of the expression.'),
45:('Antisymmetric homomorphisms and a skew block matrix','Check the biduality κ and the signs before replacing “antisymmetric” by “symmetric”.','With standard biduality, φ_L∨=φ_L. A signed κ may explain a different convention.'),
46:('q′²=p′, then q²=q','Check the letters and the denominator used in rescaling the projector.','If p²=np, then q=p/n satisfies q²=q. The displayed variables must agree with this definition.'),
47:('All closed subgroups; “loc. non ramifié”','Candidate: smooth or abelian subgroups only, or a cancelled assertion.','The α_p-lines inside a superspecial abelian surface form P¹ and have nontrivial infinitesimal deformations. The unrestricted subgroup assertion is false.'),
48:('Unibranch versus geometrically unibranch; nilpotents','Check which geometric unibranchness and reducedness hypotheses survive.','The proof requires one point in each geometric fibre and the finite unramified radicial criterion. Ordinary unibranchness alone does not state all of this.'),
49:('The reduced qualifier on Pic⁰ is deleted','Retain the reduced identity component unless smoothness is established.','In positive characteristic Picard schemes may be nonreduced. The dual of the Albanese is not automatically the whole Pic⁰ scheme.'),
50:('Cancelled fibre hypotheses; union of connected components','Check whether identity components are intended.','The union of all connected components of a fibre is the entire Picard fibre, usually not proper. The proof needs Pic⁰ or its reduced identity component.'),
51:('2g−2 in the Lefschetz count','Candidate: 2−2g.','The alternating trace is 1−2g+1. Its negativity contradicts nonnegative graph-diagonal intersection for a nonidentity automorphism.'),
52:('Hyperelliptic cokernel dimension 1','Candidate: g−2, or a restriction to genus three.','The canonical double-cover calculation gives g−2. Genus four already gives dimension two.'),
53:('Hyperelliptic fibre described as dual numbers','Check for an unstated genus-three restriction.','Ricolfi Theorem 3.6 gives g−2 square-zero generators in characteristic different from two. A single generator occurs in genus three.'),
54:('Scope of the circled “faux sous cette forme” beside Corollary 2','Determine which clause or clauses are withdrawn.','The ± ambiguity in Torelli invalidates an unqualified marked lift, but the placement of the warning does not uniquely identify the rejected clause.')
}
for n,v in edits.items():
    for key,val in zip(['reading','alternative','evidence'],v): rows[n-1][key]=val
# The preceding rows need only typographical spacing; these substitutions are editorial.
fix={'insertedA':'inserted A','betweenlocal':'between local','supply∩':'supply ∩','or⊂from':'or ⊂ from','VanishingLie':'Vanishing Lie',':sl₂':': sl₂','andpgl₂':'and pgl₂','characteristic2':'characteristic 2','labelcalligraphic':'label calligraphic','orGothic':'or Gothic','byinner':'by inner','theSL₂':'the SL₂','nonabelianH¹':'nonabelian H¹','TheV₄':'The V₄','inmath_checks':'in math_checks','versusextérieurs':'versus extérieurs','globaliffwith':'global iff with','ofW₁etT₁':'of W₁ et T₁','whetherN₁lies':'whether N₁ lies','inG₁oritsadjoint':'in G₁ or its adjoint','ForSL₂overcharacteristic≠2':'For SL₂ over characteristic ≠2','completingBru---from':'completing Bru--- from','forrank1':'for rank 1','whereasHom':'whereas Hom','changingGL₂toPGL₂changes':'changing GL₂ to PGL₂ changes','ChangingGL₂toPGL₂changes':'Changing GL₂ to PGL₂ changes','andinner':'and inner','versusinjectif':'versus injectif','beforeusing':'before using','in(7),(8)':'in (7), (8)','Candidatej′':'Candidate j′','andx′':'and x′','visibleprime':'visible prime','ForΦ':'For Φ','whileReΦ':'while Re Φ','Theplusformula':'The plus formula','rank1,2and':'ranks 1, 2 and','whetherSOorOis':'whether SO or O is','both zero andnonzero':'both zero and nonzero','andwhetherbilinearorquadraticinput':'and whether bilinear or quadratic input','Incharacteristic':'In characteristic','symmetric quotient orFrobenius':'symmetric quotient or Frobenius','missingdualchecks':'missing dual checks','Candidateu':'Candidate u','andcomplement':'and complement','dualq-form':'dual q-form','with ap-vector':'with a p-vector','unstarredmembership':'unstarred membership','Candidateindexh':'Candidate index h','andξ_ijforrowi,columnj':'and ξ_ij for row i, column j','ofe_His':'of e_H is','Proposition5has':'Proposition 5 has','andunitcondition':'and unit condition','aunit':'a unit','CandidateF₁':'Candidate F₁','quotient iszero':'quotient is zero','byresidue-field':'by residue-field','theDVR':'the DVR','CheckwhetherΣdenotes':'Check whether Σ denotes','manyplaces':'many places','Identify F′and':'Identify F′ and','strokesassert equalityorjust markalignment':'strokes assert equality or just mark alignment','andquotienttopology':'and quotient topology','differentrank':'different rank','cancelleddiagram':'cancelled diagram'}
for row in rows[:29]:
    for k in ('reading','alternative','evidence'):
        for a,b in fix.items(): row[k]=row[k].replace(a,b)
with (OUT/'readings.tsv').open('w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=list(rows[0]),delimiter='\t');w.writeheader();w.writerows(rows)
print(json.dumps({'readings':len(rows),'manually_rewritten':len(edits),'source_emendations':0}))
